function solve() {
  const solution = {
    nationalities: [],
    colors: [],
    beverages: [],
    pets: [],
    hobs: [],
  };

  const categories = ['nationalities', 'colors', 'beverages', 'pets', 'hobs'];
  const values = {
    nationalities: NATIONALITIES,
    colors: COLORS,
    beverages: BEVERAGES,
    pets: PETS,
    hobs: HOBIES,
