  // 7. The snail owner likes to go dancing.
  if (houseOf('pets', 'Snails') !== houseOf('hobs', 'Dancing')) return false;
  // 8. The person in the yellow house is a painter.
  if (houseOf('colors', 'Yellow') !== houseOf('hobs', 'Painter')) return false;
  // 9. The person in the middle house drinks milk.
  if (s.beverages[2] !== 'Milk') return false;
  // 10. The Norwegian lives in the first house.
  if (s.nationalities[0] !== 'Norwegian') return false;
  // 11. The person who enjoys reading lives in the house next to the house with the fox.
  if (!nextTo(houseOf('hobs', 'Reading'), houseOf('pets', 'Fox'))) return false;
  // 12. The painter's house is next to the house with the horse.
  if (!nextTo(houseOf('hobs', 'Painter'), houseOf('pets', 'Horse'))) return false;
  // 13. The person who plays football drinks orange juice.
  if (houseOf('hobs', 'Football') !== houseOf('beverages', 'OrangeJuice')) return false;
  // 14. The Japanese person plays chess.
  if (houseOf('nationalities', 'Japanese') !== houseOf('hobs', 'Chess')) return false;
